# ----------------------------------------------------------------------
# Model
# ----------------------------------------------------------------------
model = pulp.LpProblem("PowerGridDistribution", pulp.LpMinimize)

# Decision variables (no built‑in lower bound, we will add non‑negativity constraints)
x = {}
for p in plants:
    for s in substations:
        var_name = f"x_{p}_{s}"
        x[(p, s)] = pulp.LpVariable(var_name, lowBound=None, cat="Continuous")

# Objective: minimize total transmission cost
model += pulp.lpSum(cost[p][s] * x[(p, s)] for p in plants for s in substations), "TotalCost"

# ----------------------------------------------------------------------
# Requirements as named constraints
# ----------------------------------------------------------------------
# R1: Generation capacity of each plant
for p in plants:
    model += (
        pulp.lpSum(x[(p, s)] for s in substations) <= gen_cap[p],
        f"R1_{p}"
    )

# R2: Load must be met exactly at each substation
for s in substations:
    model += (
        pulp.lpSum(x[(p, s)] for p in plants) == load[s],
        f"R2_{s}"
    )

# R3: Line capacity limits
for p in plants:
    for s in substations:
        model += (
            x[(p, s)] <= cap[p][s],
            f"R3_{p}_{s}"
        )

# R4: Non‑negativity of shipments
for p in plants:
    for s in substations:
        model += (
            x[(p, s)] >= 0,
            f"R4_{p}_{s}"
        )

# ----------------------------------------------------------------------
# Solve
# ----------------------------------------------------------------------
model.solve(pulp.HiGHS(msg=False, timeLimit=120))

# ----------------------------------------------------------------------
# Output (optional, for verification)
# ----------------------------------------------------------------------
print(f"Status: {pulp.LpStatus[model.status]}")
print(f"Total transmission cost = {pulp.value(model.objective):.2f}")

# Print shipments (only non‑zero values for brevity)
for p in plants:
    for s in substations:
        qty = x[(p, s)].varValue
        if qty is not None and qty > 1e-6:
            print(f"{p} -> {s}: {qty:.2f} MW")
